import json
with open('/home/jeremy/.claude/projects/-srv-git-odbus-verified/f4c461eb-d25f-4247-9bd7-eddda9ade635.jsonl') as f:
    lines = f.readlines()

# Count by type
counts = {}
for l in lines:
    d = json.loads(l)
    t = d.get('type','?')
    counts[t] = counts.get(t,0)+1
print('Counts:', counts)
print('Total lines:', len(lines))

# Find the last few user and assistant messages
for l in reversed(lines):
    d = json.loads(l)
    if d.get('type') == 'message':
        role = d.get('role','?')
        parts = d.get('content',[])
