            elif isinstance(p, dict):
                texts.append(f'[{p.get(\"type\",\"?\")}]')
        if texts:
            print(f'L-{len([x for x in reversed(lines) if json.loads(x).get(\"parentUuid\") == d.get(\"uuid\")])} [{role}] \"{''.join(texts[:3])}...' if len(texts)>3 else ''.join(texts))')
" 2>/dev/null | head -20

