struct WakeRelay {
    args: Args,
}

impl WakeRelay {
    fn new(args: Args) -> Self {
        Self { args }
    }

    /// Notify the control-plane chatbot of a pending turn via D-Bus.
    async fn notify_chatbot(&self, turn_id: &str, conversation_id: Option<&str>) -> Result<()> {
        use zbus::Connection;

        let connection = Connection::session()
            .await
            .context("failed to connect to session D-Bus")?;

        // Call the chatbot's ProcessPendingTurn method
        let reply: Result<(), zbus::Error> = connection
            .call_method(
                Some(self.args.dbus_dest.as_str()),
                self.args.dbus_path.as_str(),
                Some("org.opdbus.v1.ChatResponder"),
                "ProcessPendingTurn",
                &(turn_id, conversation_id.unwrap_or("")),
            )
            .await
            .map(|_| ());

        match reply {
            Ok(()) => {
                info!(turn_id, conversation_id, "notified chatbot of pending turn");
                Ok(())
            }
            Err(zbus::Error::MethodError(name, detail, _)) => {
                // Method errors are expected if the chatbot is busy or the turn
                // was already claimed. Log and continue.
                debug!(
                    turn_id,
                    error_name = %name,
                    ?detail,
                    "chatbot notification returned error (may be expected)"
                );
                Ok(())
            }
            Err(error) => {
                warn!(turn_id, %error, "failed to notify chatbot");
                Err(error.into())
            }
        }
    }

    /// Process a wake notification by forwarding to the chatbot.
    async fn handle_wake(&self, wake: ResponderWake) {
        info!(
            request_id = %wake.request_id,
            owner_key = %wake.owner_key,
            owner_principal_id = %wake.owner_principal_id,
            conversation_id = ?wake.conversation_id,
            preview = ?wake.preview,
            "received responder wake"
        );

        if let Err(error) = self
            .notify_chatbot(&wake.request_id, wake.conversation_id.as_deref())
            .await
        {
            error!(
                request_id = %wake.request_id,
                %error,
                "failed to forward wake to chatbot"
            );
        }
    }

…
}

/// Shared state for the ChatService.
pub struct ChatServiceImpl {
    /// Active conversation cursors for cancel support.
    cancellations:
        Arc<Mutex<std::collections::HashMap<ConversationKey, tokio::sync::watch::Sender<bool>>>>,
    /// Pending approvals are scoped to principal, session and conversation.
    approvals:
        Arc<Mutex<std::collections::HashMap<ApprovalKey, tokio::sync::oneshot::Sender<bool>>>>,
    /// The sole schema method/event-chain authority.
    engine: Arc<MutationEngine>,
}

impl ChatServiceImpl {
    pub fn new(engine: Arc<MutationEngine>) -> Self {
        Self {
            cancellations: Arc::new(Mutex::new(Default::default())),
            approvals: Arc::new(Mutex::new(Default::default())),
            engine,
        }
    }
}

type ChatStream = Pin<Box<dyn Stream<Item = Result<ChatFrame, Status>> + Send + 'static>>;

async fn dispatch_chat_method(
    engine: &MutationEngine,
    chat_args: &str,
    identity: &GhostbridgeIdentity,
) -> anyhow::Result<ChatOutput> {
    let result = engine
        .dispatch_method_call_with_identity(
            ROUTER_PLUGIN_ID,
            "Chat",
            chat_args,
            Some(ROUTER_CHAT_CAPABILITY),
            &identity.principal_id,
            Some(&identity.session_id),
            Some(&identity.session_genesis),
        )
        .await?;
    let payload = result
        .get("result")
        .cloned()
        .ok_or_else(|| anyhow!("chat_router.Chat returned no result payload"))?;
