        .iter()
        .find_map(|name| ProviderType::from_str(name).ok())
        .ok_or_else(|| {
            anyhow!(
                "provider '{}' is declared but has no op-llm runtime adapter",
                names.first().map(String::as_str).unwrap_or(provider_id)
            )
