/// The doorbell of the session that asked the newest committed turn, at the
/// snapshot's revision. Only the owner's own verified turns are considered.
pub(crate) fn newest_asker(
    snapshot: &ChatResponseSnapshot,
    principal_id: &str,
) -> Option<DoorbellWake> {
…
}

//! Chat response plugin (OD-90 stage 1).
//!
//! Every chat turn ends in a response tool call, never raw model text. The
//! three response methods are those tool calls; this plugin IS their schema.
//!
//! Owner decisions (2026-09-28): a conversation belongs to the asking human's
//! principal and spans logins. Each committed turn records the session it came
//! from as provenance. An agent identity (the chain actor) authors responses
//! into the human's private scope, bound by a bridge-minted `turn_id`. Turns
//! form a per-conversation sub-chain whose order and completeness can be
//! verified from public fields alone (`conversation_id`, `turn_index`,
//! `prev_turn_hash`, `turn_hash`, `content_hash`), without reading content.
//!
//! Content fields carry `x-opdbus-private: true` (OD-91 marker). This plugin
//! only declares the marker; the chain and vector filters that honour it are
//! OD-91's work.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;
use std::collections::BTreeMap;

pub const PLUGIN_ID: &str = "chat_response";
pub const PLUGIN_VERSION: &str = "1.0.0";
/// Agents only: authors the three response methods into a human's scope.
pub const RESPOND_CAPABILITY: &str = "chat_response.respond";
/// Humans, on their own principal scope: start a conversation and read it.
pub const READ_CAPABILITY: &str = "chat_response.read";
/// Content-free commit announcement (owner key, ids and hashes only).
pub const RESPONSE_COMMITTED_SIGNAL: &str = "response_committed";

// ── Response content (private) ───────────────────────────────────────────────

/// How the user interface presents a `respond_to_user` message.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, schemars::JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum MessageType {
    Success,
    Info,
    Warning,
    Error,
}

/// Why a request cannot be performed.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, schemars::JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum RefusalCategory {
    Dangerous,
    NotAllowed,
    MissingInfo,
    PolicyViolation,
    NotSupported,
}

/// The authored content of one response. `content_hash` is the SHA-256 of
/// this value's canonical JSON (object keys sorted), so it commits to the
/// content without revealing it.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema, PartialEq)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum ResponseContent {
    /// `respond_to_user`: the answer, optionally with a validated Canvas.
    UserResponse {
        #[schemars(
            description = "The message shown to the user [PII]",
            extend("x-opdbus-private" = true)
        )]
        message: String,
        #[schemars(description = "How the message is presented")]
        message_type: MessageType,
        #[serde(default)]
        #[schemars(description = "Tool or method names the agent called to produce this response")]
        related_actions: Vec<String>,
        #[serde(default)]
        #[schemars(
            description = "json-render Canvas spec validated against the sealed json_render Canvas profile [PII]",
            extend("x-opdbus-private" = true)
        )]
        canvas: Option<serde_json::Map<String, serde_json::Value>>,
    },
    /// `request_clarification`: the agent needs more from the user.
…
}

/// Record a verified human's message as the next turn of one of their
/// conversations, then open the following turn for the agent principal
/// that may answer it. Both sides land in the same conversation chain:
/// the response's `prev_turn_hash` is the human turn's hash. Internal
/// bridge API: the door's chat operation calls it, with its own admitted
/// chat request as `request`; no transport or model can mint a turn.
/// The answer is a `chat_response` write on the responder identity's
/// zeroclowfs mount.
pub(crate) async fn open_chat_turn(
    &self,
    owner: crate::chat_response_turns::TurnOwner,
    conversation_id: &str,
    message: String,
    request: crate::chat_response_dispatch::RequestEvent,
    responder_principal_id: &str,
) -> anyhow::Result<(
    op_plugins::state_plugins::chat_response::ChatTurn,
    crate::chat_response_turns::PendingTurn,
)> {
    crate::project_dispatch::verified_session(
        self,
        &owner.principal_id,
        Some(&owner.session_id),
        Some(&owner.session_genesis),
    )
    .await
    .context("a chat turn requires the asking human's verified session")?;
    op_plugins::state_plugins::chat_response_methods::validate_uuid(
        "conversation_id",
        conversation_id,
    )?;
    anyhow::ensure!(
        crate::interceptor::load_capability_grants(responder_principal_id)
            .contains(op_plugins::state_plugins::chat_response::RESPOND_CAPABILITY),
        "the designated responder must hold chat_response.respond"
    );
    let store = self.chat_response_cozo().await?;
    let principal = owner.principal_id.clone();
    let conversation = conversation_id.to_string();
    let head = tokio::task::spawn_blocking(move || {
        store.get_chat_conversation(&principal, &conversation)
    })
    .await
    .context("chat_response conversation lookup worker failed")??
    .context("conversation does not exist in the asking principal's scope")?;
    // Reserve the answer's turn first: the registry allows one open turn
    // per conversation, so this also serializes the human message below,
    // and a refused reservation records nothing.
    let pending = self.chat_turns.open(
        owner.clone(),
        conversation_id,
        head.turn_count + 1,
        responder_principal_id,
    )?;

    // Notify the responder that a turn awaits their response (best-effort,
    // off the commit path). The responder can also poll list_pending_for_responder.
    {
        let wake = crate::responder_wake::chat_turn_wake(&pending, Some(&message));
        let responder = responder_principal_id.to_string();
        tokio::spawn(async move {
            crate::responder_wake::publish_responder_wake(wake, &responder).await;
        });
    }

    let human = match crate::chat_response_dispatch::commit_human_turn(
        self,
        &owner,
        conversation_id,
        message,
        request,
    )
    .await
    {
        Ok(human) if human.turn_index + 1 == pending.turn_index() => human,
        Ok(human) => {
            self.chat_turns.cancel(pending.turn_id());
            anyhow::bail!(
                "human message landed at turn {} but the answer was reserved at {}",
                human.turn_index,
                pending.turn_index()
            );
        }
        Err(error) => {
            self.chat_turns.cancel(pending.turn_id());
            return Err(error);
        }
    };
    Ok((human, pending))
}

/// When this Chat names a conversation the asking human already started,
/// record their message and open the answer turn for the control-plane
/// chatbot. The reply stays that identity's `respond_to_user`,

pub const RESPOND_CAPABILITY: &str = "chat_response.respond";
