255:    actor: &str,
256:    session: Option<&str>,
257:    genesis: Option<&str>,
258:    admitted: &PluginSchema,
259:    request: RequestEvent,
260:) -> Result<serde_json::Value> {
261:    let verified = project_dispatch::verified_session(engine, actor, session, genesis).await?;
262:    let caller = TurnOwner {
263:        principal_id: actor.to_owned(),
264:        session_id: verified,
265:        session_genesis: genesis
266:            .context("verified chat_response session genesis is required")?
267:            .to_owned(),
268:    };
269:    let pin = blocking({
270:        let admitted = admitted.clone();
271:        move || pin_contract(&admitted)
272:    })
273:    .await?;
274:    revalidate_boundary(engine, method, &caller, admitted, &pin).await?;
275:    let output = match method {
276:        "start_conversation" => {
277:            let input: StartConversationInput = serde_json::from_value(args.clone())
278:                .context("invalid start_conversation arguments")?;
279:            serde_json::to_value(
280:                start_conversation(engine, &caller, admitted, &pin, method, input).await?,
281:            )?
282:        }
283:        "respond_to_user" => {
284:            let input: RespondToUserInput = serde_json::from_value(args.clone())
285:                .context("invalid respond_to_user arguments")?;
286:            let (turn_id, content) = input.into_content()?;
287:            // An invalid canvas rejects the whole response before any claim.
288:            let canvas_schema_hash = match content.canvas() {
289:                Some(canvas) => Some(validate_canvas(canvas.clone()).await?),
290:                None => None,
291:            };
292:            let (turn, revision) = commit_response(
293:                engine,
294:                &caller,
295:                admitted,
296:                &pin,
297:                method,
298:                &turn_id,
299:                content,
300:                canvas_schema_hash,
301:                request,
