        .await?;
    let payload = result
        .get("result")
        .cloned()
        .ok_or_else(|| anyhow!("chat_router.Chat returned no result payload"))?;
    serde_json::from_value::<ChatOutput>(payload).context("invalid chat_router.Chat result")
}

