//! ChatService gRPC server implementation.
//!
//! Implements the `op_chat.chat.ChatService` trait from `chat.proto`.
//! Served on the op-grpc-bridge alongside StateSync, PluginService, etc.
//! for discovery through a single reflection endpoint.
#![allow(dead_code)] // many items are infrastructure for upcoming chat features
//!
//! Architecture:
//! - zeroclow owns provider/model routing (OD-28) — SendRequest carries them.
//! - gemma_brain routes to the selected model and applies compliance tags.
//! - The chatbot is a DELEGATOR — forced tool calling is mandatory; even user
//!   responses are emitted as tool calls (respond_to_user).
//! - Chat persistence flows through the memory loop → cognitive.
//! - The agent loop is bounded (≥50 steps) and cancellable.

use std::pin::Pin;
use std::str::FromStr;
use std::sync::Arc;

use anyhow::{Context, anyhow};
use op_llm::ProviderType;
use op_llm::chat::ChatManager;
use op_plugins::state_plugins::chat_router::{
    ChatInput, ChatOutput, ChatMessage, ChatRouterState,
};
use tokio::sync::Mutex;
use tokio_stream::Stream;
use tokio_stream::wrappers::ReceiverStream;
use tonic::{Request, Response, Status};
use tracing::{info, warn};

use crate::interceptor::{GhostbridgeIdentity, bridge_capability_identity};
use crate::mutation_engine::MutationEngine;
use crate::proto::chat::{
    ApproveRequest, ApproveResponse, CancelRequest, CancelResponse, ChatFrame, Heartbeat,
    SendRequest, StreamDone, StreamError, UiMessagePart, chat_frame,
    chat_service_server::ChatService,
};

const ROUTER_PLUGIN_ID: &str = "tched_router";
const ROUTER_CHAT_CAPABILITY: &str = "cap.software.zeroclow-router.chat@v1";

// Conversation/tool ids are client-controlled correlation labels, never an
// authorization boundary. Include both stable principal and verified session.
type ConversationKey = (String, String, String);
type ApprovalKey = (ConversationKey, String);

#[allow(clippy::result_large_err)]
fn conversation_key(identity: &GhostbridgeIdentity, id: &str) -> Result<ConversationKey, Status> {
    if id.is_empty() || id.len() > 128 || id.chars().any(char::is_control) {
        return Err(Status::invalid_argument("invalid conversation_id"));
    }
    Ok((
        identity.principal_id.clone(),
        identity.session_id.clone(),
        id.into(),
    ))
}

#[allow(clippy::result_large_err)]
fn chat_identity<T>(request: &Request<T>) -> Result<GhostbridgeIdentity, Status> {
    let identity = bridge_capability_identity(request.extensions())
        .ok_or_else(|| Status::unauthenticated("verified chat identity is required"))?;
    crate::grpc_server::authorize_schema_method(
        ROUTER_PLUGIN_ID,
        "Chat",
        Some(ROUTER_CHAT_CAPABILITY),
        Some(&identity),
    )?;
    Ok(identity)
}

#[allow(clippy::result_large_err)]
fn reserve_cancellation(
    cancellations: &mut std::collections::HashMap<
        ConversationKey,
        tokio::sync::watch::Sender<bool>,
    >,
    key: ConversationKey,
    cancel_tx: tokio::sync::watch::Sender<bool>,
) -> Result<(), Status> {
    if cancellations.contains_key(&key) {
        return Err(Status::already_exists(
…
        ));
    }
…
}

fn seal_is_unchanged(expected: &SealPin) -> Result<()> {
    let current = read_manifest_pinned_schema_document(&blob_catalog_dir_from_env(), PLUGIN)?;
    method_contract_admission::admit_compiled_state_contract(&current, PLUGIN)?;
    anyhow::ensure!(
        current.schema_hash == expected.schema_hash
            && current.blob.schema_json == expected.schema_json,
        "chat_response plugin seal changed during operation"
    );
    Ok(())
}

fn required_capability<'a>(schema: &'a PluginSchema, method: &str) -> Result<&'a str> {
    schema
        .methods
        .get(method)
        .with_context(|| format!("admitted {PLUGIN}.{method} declaration is absent"))?
        .required_capability
        .as_deref()
        .context("admitted chat_response method has no exact capability")
}

async fn blocking<T: Send + 'static>(
    operation: impl FnOnce() -> Result<T> + Send + 'static,
) -> Result<T> {
    tokio::task::spawn_blocking(operation)
        .await
        .context("chat_response worker failed")?
}

/// The caller's session, current exact grant and the pinned seal, rechecked
/// at each execution boundary.
async fn revalidate_boundary(
    engine: &MutationEngine,
    method: &str,
    caller: &TurnOwner,
    admitted: &PluginSchema,
    pin: &SealPin,
) -> Result<()> {
    project_dispatch::verified_session(
        engine,
        &caller.principal_id,
        Some(&caller.session_id),
        Some(&caller.session_genesis),
    )
    .await?;
    let required = required_capability(admitted, method)?;
    anyhow::ensure!(
        load_capability_grants(&caller.principal_id).contains(required),
        "current exact {required} grant is required"
    );
    let expected = pin.clone();
    blocking(move || seal_is_unchanged(&expected)).await
}

/// The asking human's session must still be valid when their turn is
/// answered; a revoked or expired session receives nothing.
async fn verify_owner(engine: &MutationEngine, owner: &TurnOwner) -> Result<()> {
    project_dispatch::verified_session(
        engine,
        &owner.principal_id,
        Some(&owner.session_id),
        Some(&owner.session_genesis),
    )
    .await
    .context("the session that asked this turn is no longer verified")?;
    Ok(())
}

fn validate_output(schema: &PluginSchema, method: &str, output: &serde_json::Value) -> Result<()> {
    let declaration = schema
        .methods
        .get(method)
        .with_context(|| format!("admitted {PLUGIN}.{method} declaration is absent"))?;
    method_contract_admission::validate_admitted_output(declaration, output)
        .context("chat_response output does not conform to the admitted sealed contract")
}

/// Validate a Canvas with the sealed json_render profile, returning the
/// renderer schema hash it was validated against.
async fn validate_canvas(canvas: serde_json::Map<String, serde_json::Value>) -> Result<String> {
    blocking(move || {
        let renderer = read_manifest_pinned_schema_document(&blob_catalog_dir_from_env(), RENDERER)
            .context("json_render is absent from the sealed catalog; a canvas cannot be validated")?;
        method_contract_admission::admit_compiled_state_contract(&renderer, RENDERER)?;
        let validator = PinnedCanvasValidator::from_manifest_pinned_schema(
            renderer.blob.schema_json.clone().into(),
            renderer.schema_hash.clone(),
        )?;
        validator
            .validate(&serde_json::Value::Object(canvas))
            .map_err(|error| {
                anyhow::anyhow!(
                    "canvas rejected by the sealed json_render Canvas profile: {error}; the response was not committed"
                )
            })?;
        Ok(renderer.schema_hash)
    })
    .await
}

