        engine: &MutationEngine,
        plugin: &str,
        method: &str,
        args: serde_json::Value,
        capability: &str,
        actor: &str,
        session: &str,
        genesis: &str,
    ) -> Result<serde_json::Value> {
        engine
            .dispatch_method_call_with_identity(
                plugin,
                method,
                &args.to_string(),
                Some(capability),
                actor,
                Some(session),
                Some(genesis),
            )
            .await
    }

    fn write_grants(path: &std::path::Path, actor: &str, capabilities: &[&str]) {
