80:    pub async fn start_execution(
81:        &self,
82:        tool_name: &str,
83:        input: Option<Value>,
84:        initiated_by: Option<String>,
85:    ) -> ExecutionRecord {
86:        let mut record = ExecutionRecord::new(tool_name, None);
87:        record.input = input.unwrap_or(Value::null());
88:        record.initiated_by = initiated_by;
89:        record.start();
90:
91:        let mut records = self.records.write().await;
92:        records.push(record.clone());
93:
94:        // Trim if over limit
95:        if records.len() > self.max_history {
96:            records.remove(0);
97:        }
