111:        let mut records = self.records.write().await;
112:        if let Some(record) = records.iter_mut().find(|r| r.id == id) {
113:            if !matches!(
114:                record.status,
115:                ExecutionStatus::Pending | ExecutionStatus::Running
116:            ) {
117:                return;
118:            }
